-- Comentarios do CTN, lote 6 (arts. 127 a 150). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='ctn' and numero between 127 and 150 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(127,'','Domicílio tributário','Na falta de eleição, pelo contribuinte ou responsável, de domicílio tributário, na forma da legislação aplicável, considera-se como tal, quanto às pessoas naturais, a sua residência habitual ou, sendo esta incerta ou desconhecida, o centro habitual de sua atividade (inciso I); quanto às pessoas jurídicas de direito privado ou às firmas individuais, o lugar da sua sede ou, em relação aos atos ou fatos que derem origem à obrigação, o de cada estabelecimento (inciso II); e, quanto às pessoas jurídicas de direito público, qualquer de suas repartições no território da entidade tributante (inciso III). O § 1º dispõe que, quando não couber a aplicação dessas regras, considera-se domicílio tributário o lugar da situação dos bens ou da ocorrência dos atos ou fatos que deram origem à obrigação. O § 2º dispõe que a autoridade administrativa pode recusar o domicílio eleito, quando impossibilite ou dificulte a arrecadação ou a fiscalização do tributo, aplicando-se então a regra do parágrafo anterior.'),
(127,'Art. 127-A','Domicílio Tributário Eletrônico','As intimações dos atos do processo poderão ser realizadas por meio de Domicílio Tributário Eletrônico (DTE), inclusive quando se tratar de intimação de procurador, nos termos das leis reguladoras do processo tributário administrativo (Lei Complementar n. 236, de 2026).'),
(128,'','Responsabilidade tributária de terceiro: regra geral','Sem prejuízo do disposto no Capítulo, a lei pode atribuir de modo expresso a responsabilidade pelo crédito tributário a terceira pessoa, vinculada ao fato gerador da respectiva obrigação, excluindo a responsabilidade do contribuinte ou atribuindo-a a este em caráter supletivo do cumprimento total ou parcial da referida obrigação.'),
(129,'','Responsabilidade por sucessão: créditos alcançados','O disposto na Seção aplica-se por igual aos créditos tributários definitivamente constituídos ou em curso de constituição à data dos atos nela referidos, e aos constituídos posteriormente aos mesmos atos, desde que relativos a obrigações tributárias surgidas até a referida data.'),
(130,'','Sucessão sobre bens imóveis','Os créditos tributários relativos a impostos cujo fato gerador seja a propriedade, o domínio útil ou a posse de bens imóveis, e bem assim os relativos a taxas pela prestação de serviços referentes a tais bens, ou a contribuições de melhoria, sub-rogam-se na pessoa dos respectivos adquirentes, salvo quando conste do título a prova de sua quitação. O parágrafo único dispõe que, no caso de arrematação em hasta pública, a sub-rogação ocorre sobre o respectivo preço.'),
(131,'','Responsabilidade pessoal por sucessão','São pessoalmente responsáveis o adquirente ou remitente, pelos tributos relativos aos bens adquiridos ou remidos (inciso I); o sucessor a qualquer título e o cônjuge meeiro, pelos tributos devidos pelo de cujus até a data da partilha ou adjudicação, limitada esta responsabilidade ao montante do quinhão do legado ou da meação (inciso II); e o espólio, pelos tributos devidos pelo de cujus até a data da abertura da sucessão (inciso III).'),
(132,'','Responsabilidade na fusão, transformação, incorporação e extinção de pessoas jurídicas','A pessoa jurídica de direito privado que resultar de fusão, transformação ou incorporação de outra ou em outra é responsável pelos tributos devidos até a data do ato pelas pessoas jurídicas de direito privado fusionadas, transformadas ou incorporadas. O parágrafo único aplica o disposto aos casos de extinção de pessoas jurídicas de direito privado, quando a exploração da respectiva atividade seja continuada por qualquer sócio remanescente, ou seu espólio, sob a mesma ou outra razão social, ou sob firma individual.'),
(133,'','Responsabilidade do adquirente de fundo de comércio ou estabelecimento','A pessoa natural ou jurídica de direito privado que adquirir de outra, por qualquer título, fundo de comércio ou estabelecimento comercial, industrial ou profissional, e continuar a respectiva exploração, sob a mesma ou outra razão social ou sob firma ou nome individual, responde pelos tributos relativos ao fundo ou estabelecimento adquirido, devidos até a data do ato, integralmente, se o alienante cessar a exploração do comércio, indústria ou atividade (inciso I), ou subsidiariamente com o alienante, se este prosseguir na exploração ou iniciar, dentro de seis meses a contar da data da alienação, nova atividade no mesmo ou em outro ramo de comércio, indústria ou profissão (inciso II). O § 1º, incluído pela Lei Complementar n. 118, de 2005, afasta o caput na alienação judicial em processo de falência (inciso I) e de filial ou unidade produtiva isolada em processo de recuperação judicial (inciso II). O § 2º afasta o § 1º quando o adquirente for sócio da sociedade falida ou em recuperação judicial, ou sociedade controlada pelo devedor (inciso I); parente, em linha reta ou colateral até o 4º grau, consanguíneo ou afim, do devedor ou de qualquer de seus sócios (inciso II); ou identificado como agente do falido ou do devedor com o objetivo de fraudar a sucessão tributária (inciso III). O § 3º dispõe que, em processo de falência, o produto da alienação judicial de empresa, filial ou unidade produtiva isolada permanecerá em conta de depósito à disposição do juízo da falência pelo prazo de 1 (um) ano, contado da data da alienação, somente podendo ser utilizado para o pagamento de créditos extraconcursais ou de créditos que preferem ao tributário.'),
(134,'','Responsabilidade de terceiros','Nos casos de impossibilidade de exigência do cumprimento da obrigação principal pelo contribuinte, respondem solidariamente com este, nos atos em que intervierem ou pelas omissões de que forem responsáveis: os pais, pelos tributos devidos por seus filhos menores (inciso I); os tutores e curadores, pelos tributos devidos por seus tutelados ou curatelados (inciso II); os administradores de bens de terceiros, pelos tributos devidos por estes (inciso III); o inventariante, pelos tributos devidos pelo espólio (inciso IV); o síndico e o comissário, pelos tributos devidos pela massa falida ou pelo concordatário (inciso V); os tabeliães, escrivães e demais serventuários de ofício, pelos tributos devidos sobre os atos praticados por eles, ou perante eles, em razão do seu ofício (inciso VI); e os sócios, no caso de liquidação de sociedade de pessoas (inciso VII). O parágrafo único dispõe que o artigo só se aplica, em matéria de penalidades, às de caráter moratório.'),
(135,'','Responsabilidade pessoal por excesso de poderes ou infração de lei','São pessoalmente responsáveis pelos créditos correspondentes a obrigações tributárias resultantes de atos praticados com excesso de poderes ou infração de lei, contrato social ou estatutos as pessoas referidas no artigo anterior (inciso I); os mandatários, prepostos e empregados (inciso II); e os diretores, gerentes ou representantes de pessoas jurídicas de direito privado (inciso III).'),
(136,'','Responsabilidade por infrações','Salvo disposição de lei em contrário, a responsabilidade por infrações da legislação tributária independe da intenção do agente ou do responsável e da efetividade, natureza e extensão dos efeitos do ato.'),
(137,'','Responsabilidade pessoal do agente por infrações','A responsabilidade é pessoal ao agente quanto às infrações conceituadas por lei como crimes ou contravenções, salvo quando praticadas no exercício regular de administração, mandato, função, cargo ou emprego, ou no cumprimento de ordem expressa emitida por quem de direito (inciso I); quanto às infrações em cuja definição o dolo específico do agente seja elementar (inciso II); e quanto às infrações que decorram direta e exclusivamente de dolo específico das pessoas referidas no art. 134, contra aquelas por quem respondem, dos mandatários, prepostos ou empregados, contra seus mandantes, preponentes ou empregadores, e dos diretores, gerentes ou representantes de pessoas jurídicas de direito privado, contra estas (inciso III, alíneas a a c).'),
(138,'','Denúncia espontânea','A responsabilidade é excluída, inclusive em relação à multa de mora, pela denúncia espontânea da infração, acompanhada, se for o caso, do pagamento do tributo devido e dos juros de mora, ou do depósito da importância arbitrada pela autoridade administrativa, quando o montante do tributo dependa de apuração (redação dada pela Lei Complementar n. 236, de 2026). O parágrafo único dispõe que não se considera espontânea a denúncia apresentada após o início de qualquer procedimento administrativo ou medida de fiscalização, relacionados com a infração.'),
(139,'','Crédito tributário: natureza','O crédito tributário decorre da obrigação principal e tem a mesma natureza desta.'),
(140,'','Crédito tributário: circunstâncias que o modificam','As circunstâncias que modificam o crédito tributário, sua extensão ou seus efeitos, ou as garantias ou os privilégios a ele atribuídos, ou que excluem sua exigibilidade, não afetam a obrigação tributária que lhe deu origem.'),
(141,'','Crédito tributário: modificação, extinção, suspensão e exclusão','O crédito tributário regularmente constituído somente se modifica ou extingue, ou tem sua exigibilidade suspensa ou excluída, nos casos previstos no CTN, fora dos quais não podem ser dispensadas, sob pena de responsabilidade funcional na forma da lei, a sua efetivação ou as respectivas garantias.'),
(142,'','Lançamento','Compete privativamente à autoridade administrativa constituir o crédito tributário pelo lançamento, assim entendido o procedimento administrativo tendente a verificar a ocorrência do fato gerador da obrigação correspondente, determinar a matéria tributável, calcular o montante do tributo devido, identificar o sujeito passivo e, sendo caso, propor a aplicação da penalidade cabível. O § 1º dispõe que a atividade administrativa de lançamento é vinculada e obrigatória, sob pena de responsabilidade funcional. O § 2º dispõe que, no lançamento destinado a prevenir a decadência de crédito tributário cuja exigibilidade houver sido suspensa na forma dos incisos II, IV e V do caput do art. 151, não será cominada multa de ofício ou multa de mora. O § 3º restringe o § 2º aos casos em que a suspensão tenha ocorrido antes do início de qualquer procedimento de ofício relativo ao crédito. O § 5º dispõe que as penalidades cominadas pelo descumprimento de obrigações tributárias, mediante lançamento de ofício, poderão ser pagas com reduções, na forma das legislações locais: 50% da penalidade, se pago integralmente no prazo de impugnação (inciso I); 40%, se parcelado nesse prazo (inciso II); 30%, se pago integralmente após esse prazo e antes da inscrição em dívida ativa (inciso III); e 20%, se parcelado após esse prazo e antes da inscrição em dívida ativa (inciso IV). O § 6º veda graduação, redução ou afastamento da penalidade em relação ao devedor contumaz, assim definido em lei específica. O § 7º dispõe que a graduação não exclui o dever de pagamento da obrigação principal, com os devidos acréscimos legais. O § 8º dispõe que a aplicação de penalidade será acompanhada de demonstração da conduta infratora de forma individualizada por sujeito passivo. O § 9º considera circunstâncias agravantes a prática dolosa de fraude, sonegação ou conluio ou a reincidência, podendo ser majorada a penalidade, observados os limites do § 1º do art. 113-A. O § 10 dispõe que os percentuais de redução do § 5º poderão ser majorados quando verificadas circunstâncias atenuantes (inciso I, alíneas a a f: cumprimento de obrigação acessória relacionada à conduta infringida; readequação às normas tributárias entre o início do procedimento fiscal e a lavratura do auto de infração; bons antecedentes fiscais; ausência de prejuízo ao erário; erro ou ignorância escusáveis quanto à matéria de fato; e pendência de julgamento da matéria em uma das hipóteses do art. 927 do Código de Processo Civil) e, para os sujeitos passivos que participem de programa de conformidade, serão de 60%, 50%, 40% e 30%, conforme as hipóteses do inciso II, alíneas a a d. Os §§ 4º e 11 constam como vetados e estão registrados como não vigentes.'),
(143,'','Lançamento: conversão de moeda estrangeira','Salvo disposição de lei em contrário, quando o valor tributário esteja expresso em moeda estrangeira, no lançamento far-se-á sua conversão em moeda nacional ao câmbio do dia da ocorrência do fato gerador da obrigação.'),
(144,'','Lançamento: legislação aplicável','O lançamento reporta-se à data da ocorrência do fato gerador da obrigação e rege-se pela lei então vigente, ainda que posteriormente modificada ou revogada. O § 1º dispõe que se aplica ao lançamento a legislação que, posteriormente à ocorrência do fato gerador, tenha instituído novos critérios de apuração ou processos de fiscalização, ampliado os poderes de investigação das autoridades administrativas, ou outorgado ao crédito maiores garantias ou privilégios, exceto, neste último caso, para o efeito de atribuir responsabilidade tributária a terceiros. O § 2º dispõe que o artigo não se aplica aos impostos lançados por períodos certos de tempo, desde que a respectiva lei fixe expressamente a data em que o fato gerador se considera ocorrido.'),
(145,'','Alteração do lançamento regularmente notificado','O lançamento regularmente notificado ao sujeito passivo só pode ser alterado em virtude de impugnação do sujeito passivo (inciso I), recurso de ofício (inciso II) e iniciativa de ofício da autoridade administrativa, nos casos previstos no art. 149 (inciso III).'),
(146,'','Modificação dos critérios jurídicos do lançamento','A modificação introduzida, de ofício ou em consequência de decisão administrativa ou judicial ou sentença arbitral proferida no âmbito da arbitragem especial tributária e aduaneira, nos critérios jurídicos adotados pela autoridade administrativa no exercício do lançamento, somente pode ser efetivada, em relação a um mesmo sujeito passivo, quanto a fato gerador ocorrido posteriormente à sua introdução (redação dada pela Lei Complementar n. 236, de 2026).'),
(147,'','Lançamento por declaração','O lançamento é efetuado com base na declaração do sujeito passivo ou de terceiro, quando um ou outro, na forma da legislação tributária, presta à autoridade administrativa informações sobre matéria de fato, indispensáveis à sua efetivação. O § 1º dispõe que a retificação da declaração por iniciativa do próprio declarante, quando vise a reduzir ou a excluir tributo, só é admissível mediante comprovação do erro em que se funde, e antes de notificado o lançamento. O § 2º dispõe que os erros contidos na declaração e apuráveis pelo seu exame serão retificados de ofício pela autoridade administrativa a que competir a revisão daquela.'),
(148,'','Arbitramento','Quando o cálculo do tributo tenha por base, ou tome em consideração, o valor ou o preço de bens, direitos, serviços ou atos jurídicos, a autoridade lançadora, mediante processo regular, arbitrará aquele valor ou preço, sempre que sejam omissos ou não mereçam fé as declarações ou os esclarecimentos prestados, ou os documentos expedidos pelo sujeito passivo ou pelo terceiro legalmente obrigado, ressalvada, em caso de contestação, avaliação contraditória, administrativa ou judicial.'),
(149,'','Lançamento de ofício e revisão','O lançamento é efetuado e revisto de ofício pela autoridade administrativa quando a lei assim o determine (inciso I); quando a declaração não seja prestada, por quem de direito, no prazo e na forma da legislação tributária (inciso II); quando a pessoa legalmente obrigada, embora tenha prestado declaração, deixe de atender, no prazo e na forma da legislação tributária, a pedido de esclarecimento formulado pela autoridade administrativa, recuse-se a prestá-lo ou não o preste satisfatoriamente, a juízo daquela autoridade (inciso III); quando se comprove falsidade, erro ou omissão quanto a qualquer elemento definido na legislação tributária como sendo de declaração obrigatória (inciso IV); quando se comprove omissão ou inexatidão, por parte da pessoa legalmente obrigada, no exercício da atividade a que se refere o artigo seguinte (inciso V); quando se comprove ação ou omissão do sujeito passivo, ou de terceiro legalmente obrigado, que dê lugar à aplicação de penalidade pecuniária (inciso VI); quando se comprove que o sujeito passivo, ou terceiro em benefício daquele, agiu com dolo, fraude ou simulação (inciso VII); quando deva ser apreciado fato não conhecido ou não provado por ocasião do lançamento anterior (inciso VIII); e quando se comprove que, no lançamento anterior, ocorreu fraude ou falta funcional da autoridade que o efetuou, ou omissão, pela mesma autoridade, de ato ou formalidade essencial (inciso IX). O parágrafo único dispõe que a revisão do lançamento só pode ser iniciada enquanto não extinto o direito da Fazenda Pública.'),
(150,'','Lançamento por homologação','O lançamento por homologação, que ocorre quanto aos tributos cuja legislação atribua ao sujeito passivo o dever de antecipar o pagamento sem prévio exame da autoridade administrativa, opera-se pelo ato em que a referida autoridade, tomando conhecimento da atividade assim exercida pelo obrigado, expressamente a homologa. O § 1º dispõe que o pagamento antecipado extingue o crédito, sob condição resolutória da ulterior homologação do lançamento. O § 2º dispõe que não influem sobre a obrigação tributária quaisquer atos anteriores à homologação, praticados pelo sujeito passivo ou por terceiro, visando à extinção total ou parcial do crédito. O § 3º dispõe que esses atos serão, porém, considerados na apuração do saldo porventura devido e, sendo o caso, na imposição de penalidade, ou sua graduação. O § 4º dispõe que, se a lei não fixar prazo à homologação, será ele de cinco anos, a contar da ocorrência do fato gerador; expirado esse prazo sem que a Fazenda Pública se tenha pronunciado, considera-se homologado o lançamento e definitivamente extinto o crédito, salvo se comprovada a ocorrência de dolo, fraude ou simulação. O § 5º, incluído pela Lei Complementar n. 236, de 2026, dispõe que, no caso de dolo, fraude ou simulação, o prazo do § 4º é contado na forma do inciso I do caput do art. 173. O § 6º dispõe que, no caso de pagamento parcial do tributo sujeito a lançamento por homologação, o prazo decadencial é contado da ocorrência do fato gerador.')
) as v(n,t,c,a)
where l.codigo='ctn' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente;
